//! Header schema for the transport; declarations and encoder were moved together.

/// Encoded header: three u64 words in little-endian order.
pub(crate) const HEADER_BYTES: usize = 4 * 8;

fn encode_header(sequence: u64, cursor: u64, lost: u64, stamp: u64) -> Vec<u8> {
    let mut bytes = Vec::with_capacity(HEADER_BYTES);
    for word in [sequence, cursor, lost, stamp] {
        bytes.extend_from_slice(&word.to_le_bytes());
    }
    bytes
}
